/* Symbolic PSP Graphics Engine (GE) command packet builders */
#include <ge_cmds.h>

#define POPS_GE_PRIM_POINTS         0U
#define POPS_GE_PRIM_LINES          1U
#define POPS_GE_PRIM_LINE_STRIP     2U
#define POPS_GE_PRIM_TRIANGLES      3U
#define POPS_GE_PRIM_TRIANGLE_STRIP 4U
#define POPS_GE_PRIM_TRIANGLE_FAN   5U
#define POPS_GE_PRIM_SPRITES        6U

#define POPS_GE_CMD(op, arg)             ((((u32)(op)) << 24) | ((u32)(arg) & 0x00FFFFFFU))
#define POPS_GE_PRIM(ptype, count)       POPS_GE_CMD(SCE_GE_CMD_PRIM, (((u32)(ptype)) << 16) | ((u32)(count)))
#define POPS_GE_XY10(op, x, y)           POPS_GE_CMD((op), (((u32)(y)) << 10) | ((u32)(x)))
#define POPS_GE_PAIR8(op, lo, hi)        POPS_GE_CMD((op), (((u32)(hi)) << 8) | ((u32)(lo)))
#define POPS_GE_TEST(op, fn, ref, mask)  POPS_GE_CMD((op), (((u32)(mask)) << 16) | (((u32)(ref)) << 8) | ((u32)(fn)))
#define POPS_GE_SOP(sfail, zfail, zpass) POPS_GE_CMD(SCE_GE_CMD_SOP, (((u32)(zpass)) << 16) | (((u32)(zfail)) << 8) | ((u32)(sfail)))
#define POPS_GE_BLEND(op, src, dst)      POPS_GE_CMD(SCE_GE_CMD_BLEND, (((u32)(op)) << 8) | (((u32)(dst)) << 4) | ((u32)(src)))
#define POPS_GE_TFUNC(fn, rgba, cd)      POPS_GE_CMD(SCE_GE_CMD_TFUNC, (((u32)(cd)) << 16) | (((u32)(rgba)) << 8) | ((u32)(fn)))

